package br.com.pousada.service;

import br.com.pousada.model.RatePlan;
import br.com.pousada.model.Reservation;
import br.com.pousada.model.ReservationStatus;
import br.com.pousada.config.DatabaseConfig;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

import java.time.LocalDate;

import static org.junit.jupiter.api.Assertions.*;

public class ReservationServiceTest {
    private static ReservationService service;

    @BeforeAll
    public static void setUp() {
        // Usar banco de teste
        System.setProperty("DB_URL", "jdbc:postgresql://localhost:5432/marealta_test");
        System.setProperty("DB_USER", "postgres");
        System.setProperty("DB_PASSWORD", "postgres");

        // Ignorar se o banco não estiver disponível
        try {
            DatabaseConfig.initializeDatabase();
            service = new ReservationService();
        } catch (Exception e) {
            System.out.println("Aviso: Testes requerem PostgreSQL em localhost:5432");
        }
    }

    @Test
    public void testCreateReservation() {
        if (service == null) return;

        LocalDate checkIn = LocalDate.of(2025, 3, 10);
        LocalDate checkOut = LocalDate.of(2025, 3, 12);

        Reservation reservation = service.createReservation(
            101, "João Silva", "joao@example.com", "12345678901",
            checkIn, checkOut, 2, RatePlan.STANDARD
        );

        assertNotNull(reservation.id);
        assertEquals(ReservationStatus.PENDING, reservation.status);
        assertEquals(2, reservation.nights);
        assertTrue(reservation.subtotal > 0);
        assertEquals(0, reservation.discount);
        assertTrue(reservation.total > 0);
    }

    @Test
    public void testNonRefundableDiscount() {
        if (service == null) return;

        LocalDate checkIn = LocalDate.of(2025, 3, 10);
        LocalDate checkOut = LocalDate.of(2025, 3, 12);

        Reservation standard = service.createReservation(
            101, "João", "joao@example.com", "12345678901",
            checkIn, checkOut, 2, RatePlan.STANDARD
        );

        Reservation nonRefundable = service.createReservation(
            102, "Maria", "maria@example.com", "98765432101",
            checkIn, checkOut, 2, RatePlan.NON_REFUNDABLE
        );

        assertEquals(0, standard.discount);
        assertTrue(nonRefundable.discount > 0);
        assertTrue(nonRefundable.total < standard.total);
    }
}

